// simplifying 2554 chars "Random Delaunay Triangulation" by tomkh. https://shadertoy.com/view/4sKyRD


//--------------------------------------------------
// 1) A helper function returning a FLOAT for wiggle
//    This replicates the old macro's logic but ensures
//    we end up with a single float, not a vec2.
//--------------------------------------------------
float H(vec2 v)
{
    // This replicates roughly: sin( 6.3 * fract(1e4 * sin( (v)*mat2(...))) + iTime )
    // but ensures we collapse it down to a float in the end.
    vec2 t = v * mat2(47, -73, 91, -37); // multiply v by matrix => vec2
    vec2 s = sin(t);                    // sin => vec2
    vec2 f = fract(1e4 * s);            // fract => vec2
    vec2 r = sin(6.3 * f + iTime);      // sin => vec2
    // Return one component (e.g. .x) so we have a single float:
    return r.x;
}

//--------------------------------------------------
// 2) Utility functions (same as in your code)
//--------------------------------------------------
float lineDist(vec2 p, vec2 a, vec2 b)
{
    vec2 v = b - a;
    float t = clamp(dot(p - a, v)/dot(v,v), 0.0, 1.0);
    return length((a + v*t) - p);
}

float cross2D(vec2 a, vec2 b)
{
    return a.x*b.y - a.y*b.x;
}

bool insideTriangle(vec2 p, vec2 A, vec2 B, vec2 C)
{
    float c1 = cross2D(B - A, p - A);
    float c2 = cross2D(C - B, p - B);
    float c3 = cross2D(A - C, p - C);
    return (c1*c2 >= 0.0 && c2*c3 >= 0.0);
}

vec3 randColor(float seed)
{
    return vec3(
        fract(sin(seed*12.9898)*43758.5453),
        fract(sin(seed*78.233 )*43758.5453),
        fract(sin(seed*37.719 )*43758.5453)
    );
}

//--------------------------------------------------
// 3) Instead of the P(...) macro, define cornerPos()
//    which uses a float wiggle
//--------------------------------------------------
vec2 cornerPos(
    vec2 base,
    vec2 floorCell, 
    int ix, int iy, 
    int k,
    float waveAmp
){
    // integer corner offset
    vec2 cornerIndex = vec2(float(ix + (k%2)), float(iy + (k/2)));

    // get a single float wiggle
    float wiggle = H(floorCell + cornerIndex);

    // shift the corner
    return base + cornerIndex + waveAmp * wiggle;
}

//--------------------------------------------------
// 4) Main with Zoom + scaled wiggle amplitude
//--------------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //-----------------------------------------
    // A) read "zoomFactor" from Buffer A
    //-----------------------------------------
    float zoomFactor = texture(iChannel0, vec2(0.5, 0.5)).x;
    // fallback if Buffer A not ready
    if(zoomFactor <= 0.0) zoomFactor = 1.0;

    //-----------------------------------------
    // B) map fragCoord -> "world" coords
    //    Larger zoomFactor => see more (zoom out)
    //-----------------------------------------
    vec2 R = iResolution.xy;
    vec2 p = (fragCoord - 0.5*R) / R.y * (8.0 * zoomFactor);

    //-----------------------------------------
    // C) scale wiggly amplitude so we don't get spikes
    //-----------------------------------------
    float waveAmp = 0.20 / zoomFactor;

    // track final color, min line-dist, etc.
    vec3  finalColor = vec3(0.0);
    float dMin       = 9999.0;
    float cDistMin   = 9999.0;

    //-----------------------------------------
    // D) loop over local cells
    //-----------------------------------------
    ivec2 cellCenter = ivec2(floor(p));
    for(int j = -1; j <= 1; j++)
    {
        for(int i = -1; i <= 1; i++)
        {
            ivec2 ij = cellCenter + ivec2(i, j);

            vec2 base      = vec2(ij);
            vec2 floorCell = base;  // used for H(...)

            // each cell => 2x2 sub-squares => k=0..3
            for(int k=0; k<4; k++)
            {
                // corners with scaled float wiggle
                vec2 h0 = cornerPos(base, floorCell, 0,0, k, waveAmp);
                vec2 h1 = cornerPos(base, floorCell, 1,0, k, waveAmp);
                vec2 h2 = cornerPos(base, floorCell, 0,1, k, waveAmp);
                vec2 h3 = cornerPos(base, floorCell, 1,1, k, waveAmp);

                // pseudo-delaunay diagonal
                bool diag0 = (length(h0 - h3) < length(h1 - h2));

                // random colors
                float seedBase = dot(floorCell, vec2(13.721, 29.123)) 
                                 + float(k)*3.97;
                vec3 colorA = randColor(seedBase + 0.1);
                vec3 colorB = randColor(seedBase + 7.9);

                if(diag0)
                {
                    // triangles: (h0,h1,h3) and (h0,h2,h3)
                    if(insideTriangle(p, h0, h1, h3))
                        finalColor = colorA;
                    if(insideTriangle(p, h0, h2, h3))
                        finalColor = colorB;

                    dMin = min(dMin, lineDist(p, h0,h1));
                    dMin = min(dMin, lineDist(p, h1,h3));
                    dMin = min(dMin, lineDist(p, h3,h0));
                    dMin = min(dMin, lineDist(p, h0,h2));
                    dMin = min(dMin, lineDist(p, h2,h3));

                    // centroid distances
                    vec2 c1 = (h0 + h1 + h3)/3.0;
                    vec2 c2 = (h0 + h2 + h3)/3.0;
                    cDistMin = min(cDistMin, length(p - c1));
                    cDistMin = min(cDistMin, length(p - c2));
                }
                else
                {
                    // triangles: (h0,h1,h2) and (h1,h2,h3)
                    if(insideTriangle(p, h0, h1, h2))
                        finalColor = colorA;
                    if(insideTriangle(p, h1, h2, h3))
                        finalColor = colorB;

                    dMin = min(dMin, lineDist(p, h0,h1));
                    dMin = min(dMin, lineDist(p, h1,h2));
                    dMin = min(dMin, lineDist(p, h2,h0));
                    dMin = min(dMin, lineDist(p, h1,h3));
                    dMin = min(dMin, lineDist(p, h2,h3));

                    // centroid distances
                    vec2 c1 = (h0 + h1 + h2)/3.0;
                    vec2 c2 = (h1 + h2 + h3)/3.0;
                    cDistMin = min(cDistMin, length(p - c1));
                    cDistMin = min(cDistMin, length(p - c2));
                }
            }
        }
    }

    //-----------------------------------------
    // E) Black edges
    //-----------------------------------------
    float edgeWidth  = 0.02;
    float edgeFactor = smoothstep(0.0, edgeWidth, dMin);
    vec3 outColor    = mix(vec3(0.0), finalColor, edgeFactor);

    //-----------------------------------------
    // F) optional centroid dots
    //-----------------------------------------
    float dotRadius  = 0.04;
float dotFactor = smoothstep(dotRadius * 0.95, dotRadius, cDistMin);
outColor = mix(vec3(1.0), outColor, dotFactor);

    fragColor = vec4(outColor, 1.0);
}

//===============================================================
// Buffer A
//===============================================================
// We store (zoomFactor, direction) in RG, to oscillate between
// zoomMin and zoomMax. Larger zoomFactor => see more => "zoom out."

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Read previous frame
    vec4 old = texture(iChannel0, fragCoord / iResolution.xy);

    float zoom = old.x;
    float dir  = old.y;

    // Initialize on first frame
    if (iFrame == 0)
    {
        zoom = 1.0;  // start somewhere in the middle
        dir  = 1.0;
    }

    // Range
    float zoomMin = 0.5;
    float zoomMax = 25.0;

    // 1) Figure out how far along we are between zoomMin and zoomMax
    //    (this goes from 0.0 when zoom=zoomMin to 1.0 when zoom=zoomMax)
    float t = (zoom - zoomMin) / (zoomMax - zoomMin);
    t = clamp(t, 0.0, 1.0);

    // 2) Define a slow speed near zoomMin and a fast speed near zoomMax
    //    You can tweak these two values (0.01 and 0.1) to taste.
    float slowSpeed = 0.00025;
    float fastSpeed = 0.50;

    // 3) Interpolate speed based on t
    float dynamicRate = mix(slowSpeed, fastSpeed, t);

    // 4) Update zoom using our dynamicRate
    zoom += dir * dynamicRate;

    // 5) Flip direction if out of bounds
    if (zoom < zoomMin)
    {
        zoom = zoomMin;
        dir  = 1.0;
    }
    else if (zoom > zoomMax)
    {
        zoom = zoomMax;
        dir  = -1.0;
    }

    // Output zoom + direction
    fragColor = vec4(zoom, dir, 0.0, 1.0);
}
